<?php
namespace Tests\Feature\Students;
use App\Models\AcademicYear; use App\Models\Enrollment; use App\Models\EnrollmentMode; use App\Models\Grade; use App\Models\SchoolClass; use App\Models\Stage; use App\Models\Student; use App\Models\User; use Database\Seeders\RolesAndPermissionsSeeder; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
abstract class StudentProfileDashboardTestCase extends TestCase {
 use RefreshDatabase; protected User $admin; protected Student $student; protected Enrollment $enrollment;
 protected function setUp():void { parent::setUp(); (new RolesAndPermissionsSeeder)->run(); $this->admin=User::factory()->create(['is_active'=>true]); $this->admin->assignRole('admin'); $year=AcademicYear::create(['name'=>'2026/2027','start_date'=>'2026-08-01','end_date'=>'2027-06-30','is_active'=>true]); $stage=Stage::create(['name'=>'Начальная школа','order'=>1,'is_active'=>true]); $grade=Grade::forceCreate(['name'=>'1 класс','stage_id'=>$stage->id,'level'=>1]); $class=SchoolClass::create(['grade_id'=>$grade->id,'code'=>'А','name_ru'=>'1-А','name_ar'=>'A','is_active'=>true]); $mode=EnrollmentMode::create(['code'=>'full_time','name_ru'=>'Очная форма','is_active'=>true]); $this->student=Student::create(['last_name_ru'=>'Иванов','first_name_ru'=>'Иван','patronymic_ru'=>'Иванович','phone'=>'+201000000000','status'=>Student::STATUS_PRE_REGISTERED,'class_id'=>$class->id,'documents'=>['father'=>['name'=>'Иванов Сергей','phone'=>'+201011111111','email'=>'father@example.test','identity'=>'AA1'],'mother'=>[],'emergency'=>[]]]); $this->enrollment=Enrollment::create(['student_id'=>$this->student->id,'academic_year_id'=>$year->id,'enrollment_mode_id'=>$mode->id,'stage_id'=>$stage->id,'grade_id'=>$grade->id,'class_id'=>$class->id,'academic_year'=>$year->name,'enrollment_date'=>'2026-08-01','enrolled_at'=>'2026-08-01','status'=>'active','is_active'=>true]); }
 protected function user(string $role,bool $active=true):User { $user=User::factory()->create(['is_active'=>$active]); if($role!=='none')$user->assignRole($role); return $user; }
}
